import logging
from typing import Any

from semantic_kernel.connectors.ai.prompt_execution_settings import PromptExecutionSettings
from semantic_kernel.utils.experimental_decorator import experimental_class

logger: logging.Logger = logging.getLogger(__name__)

# The fields that are recognized by the MistralAI chat completion endpoint and
# that can be moved between generic and MistralAI specific prompt execution settings.
_MISTRAL_AI_FIELDS: list[str] = ["temperature", "top_p", "max_tokens", "messages"]


@experimental_class
class MistralAIChatPromptExecutionSettings(PromptExecutionSettings):
    """Specific settings for the Chat Completion endpoint of MistralAI."""

    temperature: float | None = None
    top_p: float | None = None
    max_tokens: int | None = None
    messages: list[dict[str, Any]] | None = None

    def __init__(self, service_id: str | None = None, **kwargs: Any) -> None:
        """Initialize the MistralAI chat prompt execution settings.

        Args:
            service_id (str | None): The service ID to use for the request.
            kwargs (Any): Additional keyword arguments, these are attempted to parse
                into the keys of the specific prompt execution settings.

        Raises:
            NotImplementedError: If ``function_choice_behavior`` is provided, since the
                MistralAI connector does not support function calling.
        """
        if kwargs.get("function_choice_behavior") is not None or (
            kwargs.get("extension_data", {}) or {}
        ).get("function_choice_behavior") is not None:
            raise NotImplementedError("The MistralAI connector does not support function choice behavior.")
        super().__init__(service_id=service_id, **kwargs)

    @classmethod
    def from_prompt_execution_settings(
        cls, config: "PromptExecutionSettings"
    ) -> "MistralAIChatPromptExecutionSettings":
        """Create a MistralAI prompt execution settings from a generic prompt execution settings."""
        if config.function_choice_behavior is not None:
            raise NotImplementedError("The MistralAI connector does not support function choice behavior.")
        settings = cls(service_id=config.service_id)
        config.pack_extension_data()
        for field in _MISTRAL_AI_FIELDS:
            if field in config.extension_data and config.extension_data[field] is not None:
                setattr(settings, field, config.extension_data[field])
        return settings

    def update_from_prompt_execution_settings(self, config: "PromptExecutionSettings") -> None:
        """Update the MistralAI prompt execution settings from another prompt execution settings."""
        if config.service_id is not None:
            self.service_id = config.service_id
        config.pack_extension_data()
        for field in _MISTRAL_AI_FIELDS:
            if field in config.extension_data and config.extension_data[field] is not None:
                setattr(self, field, config.extension_data[field])

    def prepare_settings_dict(self, **kwargs: Any) -> dict[str, Any]:
        """Prepare the settings as a dictionary for sending to the MistralAI service."""
        return {
            "temperature": self.temperature,
            "top_p": self.top_p,
            "max_tokens": self.max_tokens,
        }
